fun toJson(value: Any?, indent: Int = 0): String {
    val sb = StringBuilder()
    serializeValue(value, sb, indent, 0)
    return sb.toString()
}

private fun serializeValue(
    value: Any?,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    when (value) {
        null -> sb.append("null")
        is Boolean -> sb.append(if (value) "true" else "false")
        is String -> serializeString(value, sb)
        is Int -> sb.append(value.toString())
        is Long -> sb.append(value.toString())
        is Float -> {
            val d = value.toDouble()
            if (d.isNaN() || d.isInfinite()) throw IllegalArgumentException("Non-finite double")
            serializeDouble(d, sb)
        }
        is Double -> {
            if (value.isNaN() || value.isInfinite()) throw IllegalArgumentException("Non-finite double")
            serializeDouble(value, sb)
        }
        is Map<*, *> -> serializeMap(value, sb, indent, level)
        is List<*> -> serializeList(value, sb, indent, level)
        is Array<*> -> serializeList(value.toList(), sb, indent, level)
        is Enum<*> -> sb.append("\"${value.name}\"")
        else -> throw IllegalArgumentException("Unsupported type: ${value::class.java.name}")
    }
}

private fun serializeDouble(value: Double, sb: StringBuilder) {
    // Kotlin's toString() for Double handles scientific notation and decimal places.
    // We just use it directly since the requirement says "Use Kotlin's toString() for doubles"
    sb.append(value.toString())
}

private fun serializeString(value: String, sb: StringBuilder) {
    sb.append('"')
    for (ch in value) {
        when (ch) {
            '"' -> sb.append("\\\"")
            '\\' -> sb.append("\\\\")
            '\b' -> sb.append("\\b")
            '\f' -> sb.append("\\f")
            '\n' -> sb.append("\\n")
            '\r' -> sb.append("\\r")
            '\t' -> sb.append("\\t")
            else -> {
                if (ch.code < 0x20) {
                    sb.append("\\u")
                    sb.append(String.format("%04x", ch.code))
                } else {
                    sb.append(ch)
                }
            }
        }
    }
    sb.append('"')
}

private fun serializeMap(
    map: Map<*, *>,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    if (map.isEmpty()) {
        sb.append("{}")
        return
    }

    // Check all keys are strings
    for (key in map.keys) {
        if (key !is String) {
            throw IllegalArgumentException("Map key must be String, got: ${key::class.java.name}")
        }
    }

    val entries = map.toList() // preserve iteration order

    if (indent == 0) {
        sb.append("{")
        for ((i, entry) in entries.withIndex()) {
            if (i > 0) sb.append(",")
            sb.append("\"${entry.key}\"")
            sb.append(":")
            serializeValue(entry.value, sb, indent, level + 1)
        }
        sb.append("}")
    } else {
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)

        sb.append("{\n")
        for ((i, entry) in entries.withIndex()) {
            sb.append(currentIndent)
            sb.append(" ") // space after : handled by key formatting? No, spec says "a space after :"
            // Actually: pretty output; ... a space after `:`
            // So format is: "key": value
            sb.append("\"${entry.key}\"")
            sb.append(": ")
            serializeValue(entry.value, sb, indent, level + 1)
            if (i < entries.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(currentIndent)
        sb.append("}")
    }
}

private fun serializeList(
    list: List<*>,
    sb: StringBuilder,
    indent: Int,
    level: Int
) {
    if (list.isEmpty()) {
        sb.append("[]")
        return
    }

    if (indent == 0) {
        sb.append("[")
        for ((i, item) in list.withIndex()) {
            if (i > 0) sb.append(",")
            serializeValue(item, sb, indent, level + 1)
        }
        sb.append("]")
    } else {
        val currentIndent = " ".repeat(level * indent)
        val nextIndent = " ".repeat((level + 1) * indent)

        sb.append("[\n")
        for ((i, item) in list.withIndex()) {
            sb.append(currentIndent)
            sb.append(" ") // indentation for array elements? 
            // Standard pretty print: each element on its own line indented by one more level
            serializeValue(item, sb, indent, level + 1)
            if (i < list.size - 1) {
                sb.append(",")
            }
            sb.append("\n")
        }
        sb.append(currentIndent)
        sb.append("]")
    }
}
