sealed class Token {
    abstract val pos: Int  // 0-based index of the token's first character
    data class Ident(val name: String, override val pos: Int) : Token()
    data class Str(val value: String, override val pos: Int) : Token()
    data class Num(val value: Double, override val pos: Int) : Token()
    data class Op(val symbol: String, override val pos: Int) : Token()
    data class Paren(val open: Boolean, override val pos: Int) : Token()
}
class TokenizeException(message: String, val pos: Int) : Exception(message)

fun tokenize(input: String): List<Token> {
    val tokens = mutableListOf<Token>()
    var i = 0
    val len = input.length

    // Helper to get the previous token for number parsing rules
    fun prevToken(): Token? = if (tokens.isEmpty()) null else tokens.last()

    // Check if we can start a number: no previous token, or prev is Op or open paren
    fun canStartNumber(): Boolean {
        val p = prevToken()
        return p == null || p is Token.Op || (p is Token.Paren && p.open)
    }

    while (i < len) {
        val c = input[i]

        // Skip whitespace
        if (c.isWhitespace()) {
            i++
            continue
        }

        when {
            // String literals: single or double quotes
            c == '"' || c == '\'' -> {
                val quoteChar = c
                val start = i
                i++
                val sb = StringBuilder()
                while (i < len) {
                    val ch = input[i]
                    if (ch == '\\') {
                        i++
                        if (i >= len) {
                            throw TokenizeException("Unterminated string escape", start)
                        }
                        val nextCh = input[i]
                        when (nextCh) {
                            'n' -> sb.append('\n')
                            't' -> sb.append('\t')
                            'r' -> sb.append('\r')
                            '\\' -> sb.append('\\')
                            '"' -> sb.append('"')
                            '\'' -> sb.append('\'')
                            else -> sb.append(nextCh)
                        }
                        i++
                    } else if (ch == quoteChar) {
                        i++
                        break
                    } else {
                        sb.append(ch)
                        i++
                    }
                }
                if (i >= len || input[i - 1] != quoteChar) {
                    // Check if we broke out because of end of string or end of input
                    // If we exited the loop because i >= len, then unterminated
                    if (i > len) {
                        // shouldn't happen
                    } else if (input[i - 1] != quoteChar) {
                        throw TokenizeException("Unterminated string", start)
                    }
                }
                tokens.add(Token.Str(sb.toString(), start))
            }

            // Identifiers, numbers, and dots for identifiers
            c.isLetter() || c == '_' -> {
                val start = i
                var j = i
                while (j < len && (input[j].isLetterOrDigit() || input[j] == '_' || input[j] == '.')) {
                    j++
                }
                // Check if it's a number starting with digits? No, identifiers start with letter or _
                val ident = input.substring(i, j)

                // Check if it looks like a number but starts with letter (invalid)
                // Actually, the spec says Identifiers: [A-Za-z_][A-Za-z0-9_.]*
                // So this is an identifier. But wait, what if it's "123"? That would be caught by digit case below.
                tokens.add(Token.Ident(ident, start))
                i = j
            }

            // Numbers: digits or dot (if preceded by valid context)
            c.isDigit() || (c == '.' && canStartNumber()) -> {
                val start = i

                // If it starts with a digit
                if (c.isDigit()) {
                    var j = i
                    while (j < len && input[j].isDigit()) {
                        j++
                    }
                    // Check for decimal point
                    if (j < len && input[j] == '.') {
                        // Look ahead to see if there's a digit after the dot
                        val afterDot = j + 1
                        if (afterDot < len && input[afterDot].isDigit()) {
                            j = afterDot
                            while (j < len && input[j].isDigit()) {
                                j++
                            }
                        } else {
                            // Malformed number: 5. is an error
                            throw TokenizeException("Malformed number", start)
                        }
                    }

                    val numStr = input.substring(i, j)
                    val num = numStr.toDouble()
                    tokens.add(Token.Num(num, start))
                    i = j
                } else if (c == '.') {
                    // Starts with dot. Check if next char is digit
                    if (i + 1 < len && input[i + 1].isDigit()) {
                        var j = i + 1
                        while (j < len && input[j].isDigit()) {
                            j++
                        }
                        val numStr = input.substring(i, j)
                        val num = numStr.toDouble()
                        tokens.add(Token.Num(num, start))
                        i = j
                    } else {
                        // Malformed number: . or standalone dot without following digits when it should be a number
                        throw TokenizeException("Malformed number", start)
                    }
                }
            }

            // Negative numbers: - only when canStartNumber() is true
            c == '-' && canStartNumber() -> {
                val start = i
                i++
                if (i >= len || !input[i].isDigit()) {
                    throw TokenizeException("Malformed number", start)
                }
                var j = i
                while (j < len && input[j].isDigit()) {
                    j++
                }
                // Check for decimal point
                if (j < len && input[j] == '.') {
                    // Look ahead to see if there's a digit after the dot
                    val afterDot = j + 1
                    if (afterDot < len && input[afterDot].isDigit()) {
                        j = afterDot
                        while (j < len && input[j].isDigit()) {
                            j++
                        }
                    } else {
                        // Malformed number: -5. is an error
                        throw TokenizeException("Malformed number", start)
                    }
                }

                val numStr = input.substring(i, j)
                val num = "-$numStr".toDouble()
                tokens.add(Token.Num(num, start))
                i = j
            }

            // Operators and parentheses
            c == '(' || c == ')' -> {
                tokens.add(Token.Paren(c == '(', i))
                i++
            }

            // Two-character operators first (longest match)
            i + 1 < len && input.substring(i, i + 2).let { it == "==" || it == "!=" || it == "<=" || it == ">=" || it == "&&" || it == "||" } -> {
                val op = input.substring(i, i + 2)
                tokens.add(Token.Op(op, i))
                i += 2
            }

            // Single-character operators
            c == '<' || c == '>' || c == '!' -> {
                tokens.add(Token.Op(c.toString(), i))
                i++
            }

            else -> {
                throw TokenizeException("Unexpected character: $c", i)
            }
        }
    }

    return tokens
}
