import datetime
from typing import List, Set, Tuple


def _parse_field(field_str: str, min_val: int, max_val: int, name_map: dict = None) -> List[int]:
    """
    Parse a single cron field and return a sorted list of valid values.

    Args:
        field_str: The string representation of the cron field.
        min_val: Minimum valid value for this field.
        max_val: Maximum valid value for this field.
        name_map: Optional mapping from names to integers (e.g., month names).

    Returns:
        A sorted list of integers representing the valid values for this field.

    Raises:
        ValueError: If the field is invalid.
    """
    if name_map is None:
        name_map = {}

    values = set()
    parts = field_str.split(',')
    for part in parts:
        # Handle step
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive, got {step}")
        else:
            range_part = part
            step = None

        # Parse the range or wildcard part
        if range_part == '*':
            start = min_val
            end = max_val
        elif '-' in range_part:
            # Handle names in ranges
            if '/' in part:
                raise ValueError("Names cannot be used with steps in a way that conflicts")
            sub_parts = range_part.split('-', 1)
            try:
                start_str = sub_parts[0]
                end_str = sub_parts[1]
            except IndexError:
                raise ValueError(f"Invalid range: {range_part}")

            # Resolve names to numbers
            if start_str.upper() in name_map:
                start = name_map[start_str.upper()]
            else:
                try:
                    start = int(start_str)
                except ValueError:
                    raise ValueError(f"Invalid value: {start_str}")

            if end_str.upper() in name_map:
                end = name_map[end_str.upper()]
            else:
                try:
                    end = int(end_str)
                except ValueError:
                    raise ValueError(f"Invalid value: {end_str}")

            if start > end:
                raise ValueError(f"Range start ({start}) is greater than end ({end})")
        else:
            # Single value or name
            try:
                val = int(range_part)
            except ValueError:
                if range_part.upper() in name_map:
                    val = name_map[range_part.upper()]
                else:
                    raise ValueError(f"Unknown name: {range_part}")

            if step is not None:
                # If a single value with step, it means start from that value to max with step
                start = val
                end = max_val
            else:
                # Single value without step
                if val < min_val or val > max_val:
                    raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")
                values.add(val)
                continue  # Skip the range logic below

        # Generate values for the range with optional step
        if step is None:
            # No step, include all values in range
            for v in range(start, end + 1):
                if v < min_val or v > max_val:
                    raise ValueError(f"Value {v} out of range [{min_val}, {max_val}]")
                values.add(v)
        else:
            # With step
            if start < min_val:
                start = min_val
            if end > max_val:
                end = max_val

            v = start
            while v <= end:
                if v < min_val or v > max_val:
                    raise ValueError(f"Value {v} out of range [{min_val}, {max_val}]")
                values.add(v)
                v += step

    if not values:
        raise ValueError("Parsed field resulted in no valid values")

    return sorted(list(values))


def _is_restricted(field_str: str) -> bool:
    """Check if a cron field is restricted (i.e., not just '*')."""
    # A field is restricted if it's not exactly '*'
    # But we need to be careful: "*/1" is effectively * but technically restricted? 
    # In Vixie cron, only "*" means unrestricted. "*/1" is considered restricted in some implementations?
    # Actually, the rule says: "if both day-of-month and day-of-week are restricted (neither field is exactly *)".
    # So we check if the original string is exactly "*".
    return field_str.strip() != '*'


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Calculate the next fire time for a standard 5-field cron expression.

    Args:
        expr: A standard 5-field cron expression.
        after: The datetime to start searching from (naive).

    Returns:
        The earliest datetime strictly after `after` that matches the cron expression.

    Raises:
        ValueError: If the expression is invalid or no match is found within 5 years.
    """
    # Parse the cron expression
    fields = expr.strip().split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have 5 fields, got {len(fields)}")

    minute_str, hour_str, dom_str, month_str, dow_str = fields

    # Name maps
    month_names = {
        'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
        'JUL': 7, 'AUG': 8, 'SEP': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12
    }
    day_names = {
        'SUN': 0, 'MON': 1, 'TUE': 2, 'WED': 3, 'THU': 4, 'FRI': 5, 'SAT': 6
    }

    # Parse each field
    try:
        minutes = _parse_field(minute_str, 0, 59)
    except ValueError as e:
        raise ValueError(f"Invalid minute field: {e}")

    try:
        hours = _parse_field(hour_str, 0, 23)
    except ValueError as e:
        raise ValueError(f"Invalid hour field: {e}")

    try:
        doms = _parse_field(dom_str, 1, 31)
    except ValueError as e:
        raise ValueError(f"Invalid day-of-month field: {e}")

    try:
        months = _parse_field(month_str, 1, 12, month_names)
    except ValueError as e:
        raise ValueError(f"Invalid month field: {e}")

    try:
        dows = _parse_field(dow_str, 0, 7, day_names)
    except ValueError as e:
        raise ValueError(f"Invalid day-of-week field: {e}")

    # Normalize day of week: 7 -> 0 (both are Sunday)
    if 7 in dows:
        dows = sorted(list(set([0 if d == 7 else d for d in dows])))

    # Determine if dom and dow are restricted
    dom_restricted = _is_restricted(dom_str)
    dow_restricted = _is_restricted(dow_str)

    # Start searching from the next minute after `after`
    # We need to find the earliest datetime strictly after `after`
    # So we start from after + 1 minute, truncated to seconds=0
    candidate = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)

    # Search limit: 5 years from after
    limit = after + datetime.timedelta(days=365 * 5 + 1)  # Account for leap years

    while candidate < limit:
        year = candidate.year
        month = candidate.month
        day = candidate.day
        hour = candidate.hour
        minute = candidate.minute

        # Check month
        if month not in months:
            # Jump to next valid month
            # Find the next valid month in the current year or next year
            found_next_month = False
            for m in months:
                if m > month:
                    # Set to first day of next valid month at 00:00
                    candidate = datetime.datetime(year, m, 1, 0, 0)
                    found_next_month = True
                    break
            if not found_next_month:
                # Go to January of next year
                candidate = datetime.datetime(year + 1, 1, 1, 0, 0)
            continue

        # Check day of month and day of week
        # Get the day of week for the candidate date (Monday=0, Sunday=6 in Python's weekday())
        # But our dows are Sunday=0, Monday=1, ..., Saturday=6
        # Python's weekday(): Monday=0, Tuesday=1, ..., Sunday=6
        # Python's isoweekday(): Monday=1, ..., Sunday=7
        python_weekday = candidate.weekday()  # Monday=0, Sunday=6

        # Convert to our dow format: Sunday=0, Monday=1, ..., Saturday=6
        if python_weekday == 6:  # Sunday
            current_dow = 0
        else:
            current_dow = python_weekday + 1

        # Determine if the day matches
        dom_match = day in doms
        dow_match = current_dow in dows

        if dom_restricted and dow_restricted:
            # Either must match (Vixie cron rule)
            day_matches = dom_match or dow_match
        else:
            # Both must match
            day_matches = dom_match and dow_match

        if not day_matches:
            # Skip to the next day
            candidate = candidate.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        # Check hour
        if hour not in hours:
            # Find the next valid hour in the current day
            found_next_hour = False
            for h in hours:
                if h > hour:
                    candidate = candidate.replace(hour=h, minute=0)
                    found_next_hour = True
                    break
            if not found_next_hour:
                # Go to the next day at 00:00
                candidate = candidate.replace(hour=0, minute=0) + datetime.timedelta(days=1)
            continue

        # Check minute
        if minute not in minutes:
            # Find the next valid minute in the current hour
            found_next_minute = False
            for m in minutes:
                if m > minute:
                    candidate = candidate.replace(minute=m)
                    found_next_minute = True
                    break
            if not found_next_minute:
                # Go to the next hour at 00 minutes
                candidate = candidate.replace(minute=0) + datetime.timedelta(hours=1)
            continue

        # All fields match!
        return candidate

    raise ValueError("No matching time found within 5 years")
