import copy


def merge(base: dict, *overrides: dict) -> dict:
    """
    Deep merge configuration layers where later overrides win.

    - Dicts are merged recursively.
    - Any other value in an override replaces the base value (lists are replaced, not concatenated).
    - A key whose override value is None deletes that key from the result.
    - A key ending in '+' appends items to the base list if it exists and is a list.
      If the base value exists but is not a list, raise TypeError.
      The '+' key itself never appears in the result.
    - Inputs are not mutated; result does not share mutable dicts/lists with inputs (deep copy).
    """
    # Start with a deep copy of the base
    result = copy.deepcopy(base)

    for override in overrides:
        _merge_into(result, override)

    return result


def _merge_into(target: dict, source: dict) -> None:
    """
    Merge source into target recursively. This mutates target in place.
    """
    for key, value in source.items():
        if isinstance(key, str) and key.endswith('+'):
            # Append mode
            list_key = key[:-1]  # Remove the '+' suffix

            if list_key in target:
                base_value = target[list_key]
                if not isinstance(base_value, list):
                    raise TypeError(
                        f"Cannot append to key '{list_key}': base value is not a list"
                    )
                # Append items from source (deep copy the items being appended)
                if isinstance(value, list):
                    for item in value:
                        target[list_key].append(copy.deepcopy(item))
                else:
                    # If the override value itself is not a list, treat it as a single item to append?
                    # The spec says: {"plugins+": ["x"]} appends the items. So the value should be a list.
                    # But let's handle non-list by treating as single item or just copying.
                    # Actually, looking at the spec: "appends the items to the base list". It implies the override value is a list.
                    # Let's assume it's always a list for append mode. If not, we can still try to append.
                    target[list_key].append(copy.deepcopy(value))
            else:
                # Missing base -> new list
                if isinstance(value, list):
                    target[list_key] = [copy.deepcopy(item) for item in value]
                else:
                    target[list_key] = [copy.deepcopy(value)]
        elif value is None:
            # Delete the key from result
            if key in target:
                del target[key]
        elif isinstance(value, dict) and key in target and isinstance(target[key], dict):
            # Recursively merge dicts
            _merge_into(target[key], value)
        else:
            # Replace with deep copy of the override value
            target[key] = copy.deepcopy(value)
