        raise TypeError("Top-level object must be a dict")

    result = {}

    def _validate_key(key: str) -> None:
        if sep in key:
            raise ValueError(f"Key '{key}' contains separator '{sep}'")

    def _flatten_recursive(current, path_parts: list):
        if isinstance(current, dict):
            if len(current) == 0:
                # Empty dict is a leaf
                path_key = sep.join(path_parts)
                result[path_key] = current
                return

            for key in current:
                _validate_key(key)
                new_path = path_parts + [key]
                _flatten_recursive(current[key], new_path)
        elif isinstance(current, list):
            if len(current) == 0:
                # Empty list is a leaf
                path_key = sep.join(path_parts)
                result[path_key] = current
                return

            for i, item in enumerate(current):
                new_path = path_parts + [str(i)]
                _flatten_recursive(item, new_path)
        else:
            # Any other value is a leaf
            path_key = sep.join(path_parts)
            result[path_key] = current

    _flatten_recursive(obj, [])
    return result


