    Unflatten a flat dict back into a nested dict/list structure.

    - A path segment that is a non-negative integer without leading zeros creates a list.
    - Lists must be dense: indices must be exactly 0..n-1, else ValueError.
    - Conflicts like {"a": 1, "a.b": 2} raise ValueError.
    """
    if not isinstance(flat, dict):
        raise TypeError("Input must be a dict")

    def _is_valid_list_index(s: str) -> bool:
        """Check if string is a non-negative integer without leading zeros."""
        if s == "0":
            return True
        if len(s) < 1 or not s.isdigit():
            return False
        # No leading zeros unless it's just "0"
        if s[0] == '0':
            return False
        return True

    def _parse_segment(segment: str):
        """Parse a segment: return (is_list_index, index_value)"""
        if _is_valid_list_index(segment):
            return (True, int(segment))
        else:
            return (False, segment)

    # Build a tree structure to track types and detect conflicts
    class Node:
        def __init__(self):
            self.type = None  # 'dict', 'list', or None (undetermined)
            self.children = {}  # For dict: key -> Node; For list: index -> Node
            self.value = None

    root = Node()

    for path_key, value in flat.items():
        if not isinstance(path_key, str):
            raise ValueError("Path keys must be strings")

        parts = path_key.split(sep) if path_key else []

        node = root

        for i, part in enumerate(parts):
            is_list_idx, idx_val = _parse_segment(part)

            # Determine expected type for this segment
            if node.type is None:
                # Undetermined parent
                if is_list_idx:
                    expected_type = 'list'
                else:
                    expected_type = 'dict'
            elif node.type == 'dict':
                if is_list_idx:
                    raise ValueError(f"Conflict at '{part}': parent is dict but segment is list index")
                expected_type = 'dict'
            elif node.type == 'list':
                if not is_list_idx:
                    raise ValueError(f"Expected list index but got non-index segment '{part}'")
                expected_type = 'list'
            else:
                raise ValueError("Invalid node state")

            # Check/create child
            if expected_type == 'dict':
                if part in node.children:
                    child = node.children[part]
                    if child.type is not None and child.type != 'dict':
                        raise ValueError(f"Conflict at '{part}': expected dict but found {child.type}")
