                    if child.type is not None and child.type != 'list':
                        raise ValueError(f"Conflict at list index {idx_val}: expected list but found {child.type}")
                    node = child
                else:
                    new_node = Node()
                    new_node.type = 'list'
                    node.children[idx_val] = new_node
                    node = new_node

        # Assign value to leaf node
        if node.value is not None:
            raise ValueError(f"Conflict at path '{path_key}': already assigned")
        node.value = value

    # Now convert tree to native structure, validating list density
    def _node_to_native(node: Node):
        if node.type == 'dict':
            d = {}
            for key, child in node.children.items():
                d[key] = _node_to_native(child)

            # If no children and has a value, it's an empty dict leaf
            if not d and node.value is not None:
                return node.value

            return d

        elif node.type == 'list':
            indices = sorted(node.children.keys())
            expected = list(range(len(indices)))
            if indices != expected:
                raise ValueError(f"List not dense: got indices {indices}, expected {expected}")

            lst = []
            for idx in indices:
                child = node.children[idx]
                lst.append(_node_to_native(child))

            return lst

        else:
            # Undetermined type - should not happen if all paths are consistent
            # If there's a value, it's a leaf
            if node.value is not None:
                return node.value
            raise ValueError("Undetermined node with no value")

    return _node_to_native(root)
