from typing import Union

Number = Union[int, float]


def evaluate(expr: str, env: dict[str, Number] | None = None) -> int | float:
    """Evaluate a small expression language.

    Grammar (lowest to highest precedence):
    1. Conditional: a ? b : c (right-associative)
    2. Logical OR: || then AND: && (short-circuit, result 0 or 1)
    3. Comparisons: == != < <= > >= (non-associative, result 0 or 1)
    4. Additive: + - (left-associative)
    5. Multiplicative: * / % (left-associative)
    6. Unary: - + ! (right-associative conceptually, but parsed as prefix)
    7. Power: ^ (right-associative)
    8. Atoms: literals, identifiers, function calls, parenthesized expressions
    """
    if env is None:
        env = {}

    tokens = tokenize(expr)
    if not tokens:
        raise SyntaxError("Empty input")

    parser = Parser(tokens, env)
    result = parser.parse_expression()

    if parser.pos < len(parser.tokens):
        raise SyntaxError(f"Unexpected token after expression: {parser.tokens[parser.pos]}")

    return result


class Token:
    def __init__(self, kind: str, value: any):
        self.kind = kind
        self.value = value

