import bisect


class IntervalSet:
    def __init__(self, intervals=()):
        self._iv = []
        for s, e in intervals:
            self.add(s, e)

    def add(self, start, end):
        if start >= end:
            return
        i = bisect.bisect_left(self._iv, (start, end))
        if i > 0 and self._iv[i - 1][1] > start:
            i -= 1
        j = i
        while j < len(self._iv) and self._iv[j][0] < end:
            start = min(start, self._iv[j][0])
            end = max(end, self._iv[j][1])
            j += 1
        self._iv[i:j] = [(start, end)]

    def remove(self, start, end):
        if start >= end:
            return
        out = []
        for s, e in self._iv:
            if e <= start or s >= end:
                out.append((s, e))
                continue
            if s < start:
                out.append((s, start))
            if e > end:
                out.append((end, e))
        self._iv = out

    def contains(self, x):
        i = bisect.bisect_left(self._iv, (x, x))
        # Check the interval at index i
        if i < len(self._iv) and self._iv[i][0] <= x < self._iv[i][1]:
            return True
        # Also check the previous interval in case bisect_left landed on the right boundary
        if i > 0:
            prev_s, prev_e = self._iv[i - 1]
            if prev_s <= x < prev_e:
                return True
        return False

    def free(self, lo, hi):
        gaps = []
        cur = lo
        for s, e in self._iv:
            if s > cur and cur < hi:
                end_gap = min(s, hi)
                if cur < end_gap:
                    gaps.append((cur, end_gap))
            if e > cur:
                cur = e
            if cur >= hi:
                break
        if cur < hi:
            gaps.append((cur, hi))
        return gaps

    def __iter__(self):
        return iter(self._iv)

    def __len__(self):
        return len(self._iv)
