import heapq
from collections import defaultdict
from typing import Optional


def route(grid: list[str]) -> tuple[int, str] | None:
    """
    Find the cheapest path from S to E in a grid with walls, cost cells, and teleport pads.

    Returns (total_cost, moves) where moves is lexicographically smallest among cheapest paths.
    Returns None if E is unreachable.
    Raises ValueError for malformed grids.
    """
    # Validate grid
    if not grid or not all(len(row) == len(grid[0]) for row in grid):
        raise ValueError("Grid rows must have equal length")

    rows = len(grid)
    cols = len(grid[0])

    start = None
    end = None
    pad_positions = defaultdict(list)  # letter -> list of (r, c)
    unknown_chars = set()
    valid_chars = set('SE.#') | set('123456789') | set('abcdefghijklmnopqrstuvwxyz')

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch not in valid_chars:
                raise ValueError(f"Unknown character '{ch}' at ({r}, {c})")
            if ch == 'S':
                if start is not None:
                    raise ValueError("Multiple S found")
                start = (r, c)
            elif ch == 'E':
                if end is not None:
                    raise ValueError("Multiple E found")
                end = (r, c)
            elif ch in 'abcdefghijklmnopqrstuvwxyz':
                pad_positions[ch].append((r, c))

    if start is None:
        raise ValueError("No S found")
    if end is None:
        raise ValueError("No E found")

    # Validate pads: each letter must appear 0 or 2 times
    for letter, positions in pad_positions.items():
        if len(positions) != 2:
            raise ValueError(f"Pad '{letter}' appears {len(positions)} times (must be 0 or 2)")

    # Direction mapping: D < L < R < T < U
    # For orthogonal moves: D, L, R, U
    directions = [
        ('D', 1, 0),   # Down
        ('L', 0, -1),  # Left
        ('R', 0, 1),   # Right
        ('U', -1, 0),  # Up
    ]

    def get_cost(r: int, c: int) -> int:
        """Get the cost of entering cell (r, c)."""
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '#':
            return float('inf')  # Wall, cannot enter
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        else:  # lowercase letter (teleport pad)
            return 1

    def get_neighbors(r: int, c: int):
        """Generate all possible moves from (r, c)."""
        # Orthogonal moves: D, L, R, U (in lexicographic order)
        for move_char, dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                cost = get_cost(nr, nc)
                if cost != float('inf'):
                    yield (nr, nc, move_char, cost)

        # Teleport moves: if current cell is a pad, can teleport to the other pad
        ch = grid[r][c]
        if ch in 'abcdefghijklmnopqrstuvwxyz':
            positions = pad_positions[ch]
            for pr, pc in positions:
                if (pr, pc) != (r, c):
                    # Cost of teleport is 2
                    yield (pr, pc, 'T', 2)

    # Dijkstra's algorithm with state (cost, path_string, r, c)
    # But storing full path strings can be expensive. Instead, we use a different approach:
    # We store for each state (r, c) the best cost and the lexicographically smallest path to achieve that cost.
    # However, since we need lexicographic order among equal-cost paths, we need to be careful.

    # State: (r, c)
    # dist[(r,c)] = (min_cost, lex_smallest_path_string)

    INF = float('inf')
    dist = {}  # (r, c) -> (cost, path_string)
    start_state = (start[0], start[1])
    dist[start_state] = (0, "")

    # Priority queue: (total_cost, path_string, r, c)
    # The path_string is used for tie-breaking. Since we want lex smallest among same cost,
    # and heapq in Python compares tuples element-wise, (cost, path_string) will work if we put cost first.
    pq = [(0, "", start[0], start[1])]

    while pq:
        total_cost, path, r, c = heapq.heappop(pq)

        state = (r, c)

        # Check if this is the current best for this state
        if state in dist:
            best_cost, best_path = dist[state]
            if total_cost > best_cost:
                continue
            if total_cost == best_cost and path > best_path:
                continue

        # If we reached the end, return immediately (since Dijkstra guarantees shortest cost,
        # and we process in order of (cost, path), the first time we pop E is the answer)
        if (r, c) == end:
            return (total_cost, path)

        # Explore neighbors
        for nr, nc, move_char, move_cost in get_neighbors(r, c):
            new_cost = total_cost + move_cost
            new_path = path + move_char

            neighbor_state = (nr, nc)

            if neighbor_state not in dist:
                dist[neighbor_state] = (new_cost, new_path)
                heapq.heappush(pq, (new_cost, new_path, nr, nc))
            else:
                existing_cost, existing_path = dist[neighbor_state]
                if new_cost < existing_cost or (new_cost == existing_cost and new_path < existing_path):
                    dist[neighbor_state] = (new_cost, new_path)
                    heapq.heappush(pq, (new_cost, new_path, nr, nc))

    return None
