import re
from typing import List, Optional, Tuple


class Version:
    """Represents a SemVer 2.0.0 version."""

    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[str] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease is not None:
            s += f"-{self.prerelease}"
        if self.build is not None:
            s += f"+{self.build}"
        return s

    def _prerelease_ids(self) -> List[str]:
        """Return list of prerelease identifiers."""
        if self.prerelease is None:
            return []
        return self.prerelease.split(".")

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # For equality, build metadata is ignored as per SemVer precedence rules for comparison
        # But actually, in SemVer, == should consider build metadata? No, the spec says build metadata is ignored for precedence.
        # The problem says "== must follow precedence too", and precedence ignores build.
        return (self.major, self.minor, self.patch, self.prerelease) == (other.major, other.minor, other.patch, other.prerelease)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        # Compare major, minor, patch
        if (self.major, self.minor, self.patch) != (other.major, other.minor, other.patch):
            return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

        # Same major.minor.patch
        pre_self = self._prerelease_ids()
        pre_other = other._prerelease_ids()

        # A version without prerelease has higher precedence than one with prerelease
        if self.prerelease is None and other.prerelease is not None:
            return False  # self >= other (since self is release, other is prerelease)
        if self.prerelease is not None and other.prerelease is None:
            return True   # self < other

        # Both have prerelease or both don't
        if self.prerelease is None and other.prerelease is None:
            return False  # equal in this part

        # Compare prerelease identifiers
        for id_self, id_other in zip(pre_self, pre_other):
            is_num_self = id_self.isdigit()
            is_num_other = id_other.isdigit()

            if is_num_self and is_num_other:
                # Both numeric: compare as integers
                int_self = int(id_self)
                int_other = int(id_other)
                if int_self != int_other:
                    return int_self < int_other
            elif is_num_self and not is_num_other:
                # Numeric has lower precedence than alphanumeric
                return True
            elif not is_num_self and is_num_other:
                return False
            else:
                # Both alphanumeric: compare as strings
                if id_self != id_other:
                    return id_self < id_other

        # If all compared identifiers are equal, the shorter list has lower precedence
        if len(pre_self) != len(pre_other):
            return len(pre_self) < len(pre_other)

        return False  # Equal

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return not (self <= other)

    def __ge__(self, other):
        return not (self < other)

    def __ne__(self, other):
        return not self.__eq__(other)


def parse(v: str) -> Version:
    """Parse a SemVer 2.0.0 version string."""
    # Strip leading 'v' or '='
    s = v.strip()
    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    # Regex for SemVer 2.0.0
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    # No leading zeros in numeric parts
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$'

    match = re.match(pattern, s)
    if not match:
        raise ValueError(f"Invalid version: {v}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = match.group(4)
    build = match.group(5)

    return Version(major, minor, patch, prerelease, build)


def _parse_version_or_none(v: str) -> Optional[Version]:
    """Parse a version string, returning None if invalid."""
    try:
        return parse(v)
    except ValueError:
        return None


def _is_x_range_part(part: str) -> bool:
    """Check if a part is an X-range wildcard (x, X, *)."""
    return part.lower() == 'x' or part == '*'


def _expand_partial_version(v_str: str) -> Optional[Tuple[Version, Version]]:
    """
    Expand a partial version string into a range (lower_bound, upper_bound).
    Returns None if invalid.
    For X-ranges like `1`, `1.x`, `1.2.*`, etc., returns the inclusive lower and exclusive upper bounds.
    """
    # Remove leading v or =
    s = v_str.strip()
    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    # Split by dots
    parts = s.split('.')

    # Determine how many parts are specified and which are wildcards
    num_parts = len(parts)

    # Check for invalid characters in non-wildcard parts
    for i, part in enumerate(parts):
        if _is_x_range_part(part):
            continue
        # Must be a valid number
        if not re.match(r'^(0|[1-9]\d*)$', part):
            return None

    # All wildcards or all numbers? Mixed is tricky. Let's handle standard cases.
    # If any part after the first non-wildcard is a wildcard, it's invalid? No, `1.x.y` is not standard.
    # Standard X-ranges: `1`, `1.x`, `1.2.*`, `X`, `x`, `*`

    # Count how many leading parts are wildcards or numbers
    # If we have a wildcard in the middle, it's typically treated as the rest being 0? 
    # Actually, npm semver treats `1.x.y` as invalid if y is not * or x. Let's be strict.

    # Find the last non-wildcard part
    last_non_wild_idx = -1
    for i in range(len(parts) - 1, -1, -1):
        if not _is_x_range_part(parts[i]):
            last_non_wild_idx = i
            break

    if last_non_wild_idx == -1:
        # All wildcards, e.g., `*`, `x.x.x`
        return (Version(0, 0, 0), None)  # Lower bound 0.0.0, no upper bound

    # Check that all parts after last_non_wild_idx are wildcards
    for i in range(last_non_wild_idx + 1, len(parts)):
        if not _is_x_range_part(parts[i]):
            return None

    # Construct the base version from the specified parts
    try:
        major = int(parts[0]) if last_non_wild_idx >= 0 else 0
        minor = int(parts[1]) if last_non_wild_idx >= 1 and not _is_x_range_part(parts[1]) else 0
        patch = int(parts[2]) if last_non_wild_idx >= 2 and not _is_x_range_part(parts[2]) else 0

        # Validate that wildcard parts are actually wildcards
        for i in range(last_non_wild_idx + 1, len(parts)):
            if not _is_x_range_part(parts[i]):
                return None

    except (ValueError, IndexError):
        return None

    lower = Version(major, minor, patch)

    # Determine upper bound
    if last_non_wild_idx == 0:
        # e.g., `1` or `1.x` -> >=1.0.0 <2.0.0
        upper = Version(major + 1, 0, 0)
    elif last_non_wild_idx == 1:
        # e.g., `1.2` or `1.2.*` -> >=1.2.0 <1.3.0
        upper = Version(major, minor + 1, 0)
    else:
        # e.g., `1.2.3` (exact) -> no upper bound in this context? 
        # But for X-range expansion, if it's exact, we treat it as >=v <v+0.0.1? No.
        # Actually, the function is used for partial versions in comparators.
        # If it's an exact version, we don't expand to a range here; the caller handles exact matches.
        # But for hyphen ranges and tilde/caret, we need bounds.
        # For an exact version like `1.2.3`, the lower bound is 1.2.3 and there's no implicit upper bound from X-range logic.
        return (lower, None)

    return (lower, upper)


def _parse_comparator_set(rng: str) -> List[Tuple[str, Version]]:
    """
    Parse a comparator set (whitespace-separated comparators).
    Returns a list of (operator, version) tuples.
    Raises ValueError if invalid.
    """
    rng = rng.strip()
    if not rng or rng == '*':
        return []  # Empty set matches everything

    comparators = []
    # Split by whitespace
    tokens = rng.split()

    for token in tokens:
        # Parse comparator
        # Operators: <, <=, >, >=, =, or none (which means =)
        op = '='
        version_str = token

        if token.startswith('>='):
            op = '>='
            version_str = token[2:]
        elif token.startswith('<='):
            op = '<='
            version_str = token[2:]
        elif token.startswith('>'):
            op = '>'
            version_str = token[1:]
        elif token.startswith('<'):
            op = '<'
            version_str = token[1:]
        elif token.startswith('='):
            op = '='
            version_str = token[1:]

        if not version_str:
            raise ValueError(f"Invalid comparator: {token}")

        # Parse version
        ver = parse(version_str)
        comparators.append((op, ver))

    return comparators


def _satisfies_comparator_set(version: Version, comparators: List[Tuple[str, Version]]) -> bool:
    """Check if a version satisfies a comparator set."""
    if not comparators:
        return True

    # Check if any comparator has a prerelease with the same MAJOR.MINOR.PATCH as the version
    # This is for prerelease satisfaction rules
    has_matching_prerelease_comparator = False
    for op, comp_ver in comparators:
        if (comp_ver.major == version.major and 
            comp_ver.minor == version.minor and 
            comp_ver.patch == version.patch and 
            comp_ver.prerelease is not None):
            has_matching_prerelease_comparator = True
            break

    # If the version being tested has a prerelease, it must satisfy all comparators AND
    # there must be at least one comparator with a matching MAJOR.MINOR.PATCH and a prerelease.
    if version.prerelease is not None:
        if not has_matching_prerelease_comparator:
            return False

    for op, comp_ver in comparators:
        if op == '<':
            if not (version < comp_ver):
                return False
        elif op == '<=':
            if not (version <= comp_ver):
                return False
        elif op == '>':
            if not (version > comp_ver):
                return False
        elif op == '>=':
            if not (version >= comp_ver):
                return False
        elif op == '=':
            if not (version == comp_ver):
                return False

    return True


def _satisfies_range(version_str: str, range_str: str) -> bool:
    """Check if a version string satisfies a range string."""
    version = parse(version_str)

    # Split range by ||
    sets = range_str.split('||')

    for set_str in sets:
        comparators = _parse_comparator_set(set_str)
        if _satisfies_comparator_set(version, comparators):
            return True

    return False


def satisfies(version: str, rng: str) -> bool:
    """Check if a version satisfies a range."""
    try:
        return _satisfies_range(version, rng)
    except ValueError:
        raise


def max_satisfying(versions: List[str], rng: str) -> Optional[str]:
    """Return the highest version that satisfies the range, or None."""
    best = None
    best_version = None

    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        if _satisfies_range(v_str, rng):
            if best_version is None or v > best_version:
                best = v_str
                best_version = v

    return best


def _expand_hyphen_range(lower_str: str, upper_str: str) -> Tuple[List[Tuple[str, Version]], List[Tuple[str, Version]]]:
    """
    Expand a hyphen range `lower - upper` into two comparator sets.
    The lower bound is inclusive (>=), the upper bound is exclusive (<).
    Returns ((>=lower_comp), (<upper_comp)) as two lists of comparators.
    """
    lower_ver = parse(lower_str)
    upper_ver = parse(upper_str)

    # Expand partial versions
    lower_expanded = _expand_partial_version(lower_str)
    if lower_expanded is None:
        raise ValueError(f"Invalid hyphen range lower bound: {lower_str}")

    upper_expanded = _expand_partial_version(upper_str)
    if upper_expanded is None:
        raise ValueError(f"Invalid hyphen range upper bound: {upper_str}")

    lower_final, _ = lower_expanded
    _, upper_final = upper_expanded

    # Lower bound: >= lower_final
    lower_set = [('>=', lower_final)]

    # Upper bound: < upper_final (exclusive)
    # If upper_final is None (no upper bound), this shouldn't happen in a hyphen range.
    if upper_final is None:
        raise ValueError("Invalid hyphen range: no upper bound")

    upper_set = [('<', upper_final)]

    return lower_set, upper_set


def _expand_tilde_range(tilde_str: str) -> Tuple[List[Tuple[str, Version]], List[Tuple[str, Version]]]:
    """
    Expand a tilde range `~version` into (>=lower, <upper).
    """
    ver = parse(tilde_str)

    # Expand partial version to get bounds
    expanded = _expand_partial_version(tilde_str)
    if expanded is None:
        raise ValueError(f"Invalid tilde range: {tilde_str}")

    lower, upper = expanded

    if upper is None:
        # Exact version or no upper bound? Tilde with exact version should have an upper bound.
        # Actually, `~1.2.3` means >=1.2.3 <1.3.0. So we need to compute the upper bound manually.
        # If the input was exact, _expand_partial_version returns (v, None). We need to determine the cap.
        # Tilde caps at the next minor for patch-level, next major for minor-level, etc.
        if ver.prerelease is not None:
            # Prereleases in tilde ranges are tricky. npm semver treats `~1.2.3-alpha` as >=1.2.3-alpha <1.3.0
            pass

        # Determine the cap based on how many parts were specified
        # If we have 1.2.3, cap is 1.3.0
        # If we have 1.2, cap is 1.3.0
        # If we have 1, cap is 2.0.0

        # Re-parse to see how many parts were in the original string
        s = tilde_str.strip()
        if s.startswith('~'):
            s = s[1:]
        if s.startswith('v') or s.startswith('='):
            s = s[1:]

        parts = s.split('.')
        # Count non-wildcard parts at the start
        num_specified = 0
        for part in parts:
            if _is_x_range_part(part):
                break
            num_specified += 1

        if num_specified == 0:
            raise ValueError("Invalid tilde range")
        elif num_specified == 1:
            upper = Version(ver.major + 1, 0, 0)
        elif num_specified == 2:
            upper = Version(ver.major, ver.minor + 1, 0)
        else:
            # 3 or more parts
            upper = Version(ver.major, ver.minor, ver.patch + 1)

    return [('>=', lower), ('<', upper)]


def _expand_caret_range(caret_str: str) -> Tuple[List[Tuple[str, Version]], List[Tuple[str, Version]]]:
    """
    Expand a caret range `^version` into (>=lower, <upper).
    """
    ver = parse(caret_str)

    # Determine the cap based on the major version and how many parts are specified
    s = caret_str.strip()
    if s.startswith('^'):
        s = s[1:]
