        else:
            # Fixed-length tuple
            if len(value) != len(tuple_types):
                raise LoadError(path, f"expected tuple of length {len(tuple_types)}, got {len(value)}")
            result = []
            for i, (item, t) in enumerate(zip(value, tuple_types)):
                item_path = f"{path}[{i}]"
                result.append(_check_type(item, t, item_path))
            return tuple(result)

    # Handle dataclasses
    if _is_dataclass(expected_type):
        if not isinstance(value, dict):
            raise LoadError(path, f"expected dict for dataclass {expected_type.__name__}, got {type(value).__name__}")
        return load(expected_type, value, path)

    # Fallback: just return the value as-is (shouldn't happen with proper types)
    return value


def load(cls: type, data: Any, path: str = "$") -> Any:
    """
    Build an instance of a dataclass type `cls` from JSON-like `data`.

    Args:
        cls: The dataclass type to instantiate.
        data: The JSON-like data (dict, list, etc.).
        path: The current path in the data structure for error reporting.

    Returns:
        An instance of cls with validated and converted data.

    Raises:
        LoadError: If validation fails.
    """
    if not dataclasses.is_dataclass(cls):
        raise TypeError(f"{cls} is not a dataclass")

    # Get type hints for the dataclass fields
    try:
        hints = get_type_hints(cls)
    except Exception as e:
        # Fallback to __annotations__ if get_type_hints fails
        hints = getattr(cls, '__annotations__', {})

    if not isinstance(data, dict):
        raise LoadError(path, f"expected dict for dataclass {cls.__name__}, got {type(data).__name__}")

    # Get field info
    fields = dataclasses.fields(cls)
    field_map = {f.name: f for f in fields}

    # Check for unknown keys
    for key in data:
        if key not in field_map:
            raise LoadError(f"{path}.{key}", f"unknown key '{key}'")

    # Build the instance
    kwargs = {}
    for field in fields:
        name = field.name
        if name in data:
            value = data[name]
            field_path = f"{path}.{name}"
            expected_type = hints.get(name, Any)
            validated_value = _check_type(value, expected_type, field_path)
            kwargs[name] = validated_value
        else:
            # Field is missing
            if field.default is not dataclasses.MISSING:
                kwargs[name] = field.default
            elif field.default_factory is not dataclasses.MISSING:
                kwargs[name] = field.default_factory()
            else:
                raise LoadError(f"{path}.{name}", f"missing required field '{name}'")

    return cls(**kwargs)
