#!/usr/bin/env bash
set -euo pipefail

# Check if no arguments provided
if [ $# -eq 0 ]; then
    echo "Usage: solution.sh LOGFILE..." >&2
    exit 1
fi

# Collect all input streams (files or stdin) into a temporary file or process substitution
# We need to handle .gz files with zcat, regular files with cat, and "-" for stdin
# Also need to detect missing input files

tmpfile=$(mktemp)
trap 'rm -f "$tmpfile"' EXIT

for arg in "$@"; do
    if [ "$arg" = "-" ]; then
        cat >> "$tmpfile"
    elif [ ! -e "$arg" ]; then
        echo "Error: file '$arg' not found" >&2
        exit 1
    elif [[ "$arg" == *.gz ]]; then
        zcat "$arg" >> "$tmpfile"
    else
        cat "$arg" >> "$tmpfile"
    fi
done

# Now process the tmpfile with awk using mawk-compatible syntax
awk '
BEGIN {
    malformed = 0
    requests = 0
}
{
    line = $0

    # Try to parse combined log format:
    # IP - - [date] "METHOD PATH PROTOCOL" STATUS SIZE "REFERER" "USERAGENT"
    # The key challenge is parsing the quoted request string and handling potential variations

    # First, find the IP address (first field)
    ip = $1

    # Check basic structure: we expect at least some fields
    # Find the opening bracket for date
    date_start = index(line, "[")
    if (date_start == 0) {
        malformed++
        next
    }

    # Find the closing bracket for date
    date_end = index(substr(line, date_start), "]")
    if (date_end == 0) {
        malformed++
        next
    }
    date_end = date_start + date_end

    # After the date, we expect a space and then a quoted request string
    rest = substr(line, date_end + 1)

    # Skip leading spaces
    gsub(/^[ \t]+/, "", rest)

    # The request should start with a quote
    if (substr(rest, 1, 1) != "\"") {
        malformed++
        next
    }

    # Find the closing quote for the request string
    req_end = index(substr(rest, 2), "\"")
    if (req_end == 0) {
        malformed++
        next
    }
    req_end = 2 + req_end - 1  # Adjust position

    request_str = substr(rest, 2, req_end - 2)

    # After the closing quote of request, we expect status and size
    after_req = substr(rest, req_end + 1)
    gsub(/^[ \t]+/, "", after_req)

    # Split after_req to get status and size
    n = split(after_req, parts, /[ \t]+/)
    if (n < 2) {
        malformed++
        next
    }

    status = parts[1]
    size_str = parts[2]

    # Validate status is numeric
    if (status !~ /^[0-9]+$/) {
        malformed++
        next
    }

    # Parse the request string to get method, path, protocol
    # Request format: METHOD PATH PROTOCOL
    n_req = split(request_str, req_parts, /[ \t]+/)
    if (n_req < 2) {
        malformed++
        next
    }

    path = req_parts[2]

    # Remove query string from path
    qpos = index(path, "?")
    if (qpos > 0) {
        path = substr(path, 1, qpos - 1)
    }

    # Handle size: "-" means 0
    if (size_str == "-") {
        size = 0
    } else if (size_str ~ /^[0-9]+$/) {
        size = size_str + 0
    } else {
        malformed++
        next
    }

    # Valid line
    requests++

