    print "malformed: " malformed

    print "status:"
    # Sort status codes ascending - collect them first
    n_statuses = 0
    for (s in status_count) {
        n_statuses++
        statuses[n_statuses] = s
    }
    # Simple insertion sort for status codes (numeric)
    for (i = 2; i <= n_statuses; i++) {
        key = statuses[i] + 0
        j = i - 1
        while (j >= 1 && (statuses[j] + 0) > key) {
            statuses[j+1] = statuses[j]
            j--
        }
        statuses[j+1] = key ""
    }
    for (i = 1; i <= n_statuses; i++) {
