    # Collect all IPs
    n_ips = 0
    for (ip in ip_bytes) {
        n_ips++
        ips[n_ips] = ip
    }
    # Sort by bytes descending, then by IP ascending
    # Insertion sort
    for (i = 2; i <= n_ips; i++) {
        key_ip = ips[i]
        key_bytes = ip_bytes[key_ip]
        j = i - 1
        while (j >= 1) {
            curr_ip = ips[j]
            curr_bytes = ip_bytes[curr_ip]
            # Compare: higher bytes first; if equal, lower IP (string compare) first
            if (curr_bytes > key_bytes) {
