    # Also allows .5 style
    # Pattern: ^[+-]?([0-9]+\.?[0-9]*|[0-9]*\.[0-9]+)$
    tmp = s
    if (tmp ~ /^[+-]?[0-9]+\.?[0-9]*$/) return 1
    if (tmp ~ /^[+-]?\.[0-9]+$/) return 1
    return 0
}

function parse_record(line, fields, n_fields,    i, c, in_q, field, nf) {
    # Parse a single CSV record from line, handling quoted fields with embedded newlines already resolved?
    # No, this function parses one logical record. But our input might have lines split across physical lines.
    # We handle multi-line records in the main loop by accumulating until the quote is closed.

    # Actually, let us restructure: we accumulate physical lines into a buffer until we have a complete record.
    # Then we parse that buffer into fields.
}

# Main processing happens when we have a complete record
function process_record(buffer,    i, c, in_q, field, nf, fields_arr) {
