#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 1 ]]; then
    echo "Usage: solution.sh FILE" >&2
    exit 1
fi

FILE="$1"

if [[ ! -f "$FILE" ]]; then
    echo "$FILE: not found" >&2
    exit 1
fi

# We'll use awk to process the file line by line.
# mawk is POSIX awk compliant, so we avoid gawk extensions.

awk '
BEGIN {
    lineno = 0
    error_found = 0
}

function trim(s) {
    # Trim leading and trailing whitespace (spaces and tabs)
    gsub(/^[ \t]+/, "", s)
    gsub(/[ \t]+$/, "", s)
    return s
}

function escape_single_quote(s,    result, i, c) {
    # Escape single quotes for use inside single-quoted shell strings.
    # Replace each '\'' with '\''\'''\''
    result = ""
    for (i = 1; i <= length(s); i++) {
        c = substr(s, i, 1)
        if (c == "\047") {  # single quote
            result = result "\047\\\047\047"
        } else {
            result = result c
        }
    }
    return result
}

{
    lineno++

    # Skip blank lines and comment lines
    line = $0

    # Trim leading whitespace to check if blank or comment
    trimmed = trim(line)
    if (trimmed == "") next
    if (substr(trimmed, 1, 1) == "#") next

    # Check for optional "export " prefix
    work = trimmed
    has_export = 0
    if (match(work, /^export[ \t]+/)) {
        has_export = 1
        work = substr(work, RSTART + RLENGTH)
    }

    # Now work should be KEY=VALUE or just KEY= (empty value)
    # Find the first = sign
    eq_pos = index(work, "=")
    if (eq_pos == 0) {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        error_found = 1
        exit 1
    }

    key = substr(work, 1, eq_pos - 1)
    value_part = substr(work, eq_pos + 1)

    # Validate key: must match [A-Za-z_][A-Za-z0-9_]*
    if (key == "" || !match(key, /^[A-Za-z_][A-Za-z0-9_]*$/)) {
        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
        error_found = 1
        exit 1
    }

    # Process the value part
    final_value = ""
    remaining = value_part

    if (remaining == "") {
        # Empty value
        final_value = ""
    } else {
        first_char = substr(remaining, 1, 1)

        if (first_char == "\047") {
            # Single-quoted value
            # Find the closing single quote
            close_pos = index(substr(remaining, 2), "\047")
            if (close_pos == 0) {
                print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
                error_found = 1
                exit 1
            }
            # The content is between the first and closing quote
            final_value = substr(remaining, 2, close_pos - 1)
            after_quote = substr(remaining, close_pos + 1)
            # After the closing quote, must be empty or a comment
            trimmed_after = trim(after_quote)
            if (trimmed_after != "" && substr(trimmed_after, 1, 1) != "#") {
                print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
                error_found = 1
                exit 1
            }
        } else if (first_char == "\"") {
            # Double-quoted value
            # We need to parse escape sequences: \n, \", \\
            # And find the closing double quote.
            # Also handle comments after the closing quote.

            i = 2  # Start after opening quote
            len = length(remaining)
            final_value = ""
            found_close = 0

            while (i <= len) {
                c = substr(remaining, i, 1)
                if (c == "\\") {
                    # Check next character
                    if (i + 1 > len) {
                        print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
                        error_found = 1
                        exit 1
                    }
                    nc = substr(remaining, i + 1, 1)
                    if (nc == "n") {
                        final_value = final_value "\n"
                        i += 2
                    } else if (nc == "\"") {
                        final_value = final_value "\""
                        i += 2
                    } else if (nc == "\\") {
                        final_value = final_value "\\"
                        i += 2
                    } else {
                        # Other escape: keep as is (backslash followed by the character)
                        final_value = final_value nc
                        i += 2
                    }
                } else if (c == "\"") {
                    found_close = 1
                    i++
                    break
                } else {
                    final_value = final_value c
                    i++
                }
            }

            if (!found_close) {
                print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
                error_found = 1
                exit 1
            }

            # After the closing quote, must be empty or a comment
            after_quote = substr(remaining, i)
            trimmed_after = trim(after_quote)
            if (trimmed_after != "" && substr(trimmed_after, 1, 1) != "#") {
                print FILENAME ":" lineno ": invalid line" > "/dev/stderr"
                error_found = 1
                exit 1
            }
        } else {
            # Unquoted value: taken literally up to an unquoted " #" (space then hash)
            # But we need to be careful: " #" means a space followed by # that is not inside quotes.
            # Since there are no quotes here, we just look for " #" pattern.
            # However, we must ensure the # is preceded by a space and is not part of the value.

            # Find the first occurrence of " #" where it starts a comment.
            # We scan character by character.
            len = length(remaining)
            final_value = ""
            found_comment = 0

            i = 1
            while (i <= len) {
                c = substr(remaining, i, 1)
                if (c == " ") {
                    # Check if next character is #
                    if (i + 1 <= len && substr(remaining, i + 1, 1) == "#") {
                        # This starts a comment
                        found_comment = 1
                        break
                    }
                }
                final_value = final_value c
                i++
            }

            if (!found_comment) {
                # No comment found, the entire remaining string is the value
                final_value = remaining
            }

            # Trim trailing spaces and tabs from final_value
            final_value = trim(final_value)
        }
    }

    # Store the key-value pair. We need to handle duplicates: later value wins but keeps its LATER position.
    # We will collect all keys in order of their LAST occurrence, and for each key, store the last value.

    # Track order of last occurrences
    if (!(key in seen_keys)) {
        seen_keys[key] = 1
        key_order[++num_keys] = key
        values[key] = final_value
    } else {
        # Key already seen, update the value but keep position? 
        # The requirement says: "If a key repeats, the later value wins but keeps its LATER position (print it once, at its last occurrence)"
        # So we need to move the key to its latest position in the output order.
        values[key] = final_value

        # Remove key from its old position and add to the end
        # Find the old index of this key in key_order
        for (j = 1; j <= num_keys; j++) {
            if (key_order[j] == key) {
                # Remove it by shifting elements
                for (k = j; k < num_keys; k++) {
                    key_order[k] = key_order[k + 1]
                }
                num_keys--
                break
            }
        }
        # Add to the end
        num_keys++
        key_order[num_keys] = key
    }
}

END {
    if (error_found) exit 1

    for (i = 1; i <= num_keys; i++) {
        k = key_order[i]
        v = values[k]
        escaped_v = escape_single_quote(v)
        print "export " k "\047" escaped_v "\047"
    }
}
' "$FILE"
