#!/usr/bin/env bash

set -euo pipefail

# Defaults
N=10
CASE_INSENSITIVE=false

# Parse options
while getopts ":n:i" opt; do
    case "$opt" in
        n)
            # Check if N is a positive integer
            if ! [[ "$OPTARG" =~ ^[0-9]+$ ]] || [ "$OPTARG" -le 0 ]; then
                echo "Usage: solution.sh [-n N] [-i]" >&2
                exit 2
            fi
            N="$OPTARG"
            ;;
        i)
            CASE_INSENSITIVE=true
            ;;
        :)
            echo "Usage: solution.sh [-n N] [-i]" >&2
            exit 2
            ;;
        *)
            echo "Usage: solution.sh [-n N] [-i]" >&2
            exit 2
            ;;
    esac
done

# Process stdin with awk
awk -v n="$N" -v case_insensitive="$CASE_INSENSITIVE" '
BEGIN {
    # No special begin actions needed
}
{
    line = $0
    while (match(line, /[A-Za-z0-9'\''']+/) ) {
        token = substr(line, RSTART, RLENGTH)
        line = substr(line, RSTART + RLENGTH)

        # Strip leading apostrophes
        while (substr(token, 1, 1) == "'\''") {
            token = substr(token, 2)
        }
        # Strip trailing apostrophes
        while (length(token) > 0 && substr(token, length(token), 1) == "'\''") {
            token = substr(token, 1, length(token) - 1)
        }

        # Skip if empty or only apostrophes (now empty after stripping)
        if (length(token) == 0) {
            continue
        }

        # Convert to lowercase if case-insensitive
        if (case_insensitive) {
            token = tolower(token)
        }

        counts[token]++
    }
}
END {
    # Collect all words into an array for sorting
    num_words = 0
    for (word in counts) {
        num_words++
        words[num_words] = word
        word_counts[num_words] = counts[word]
    }

    # Simple selection sort to get top N by count desc, then word asc (byte order)
    # We need to sort the first N elements properly
    # Since mawk does not have asort, we do a simple approach:
    # Find the best candidate repeatedly

    limit = n
    if (num_words < limit) {
        limit = num_words
    }

    for (i = 1; i <= limit; i++) {
        # Find the index of the best word among remaining (i to num_words)
        best_idx = i
        for (j = i + 1; j <= num_words; j++) {
            # Compare: higher count first, then lower word in byte order (ascending)
            if (word_counts[j] > word_counts[best_idx]) {
                best_idx = j
            } else if (word_counts[j] == word_counts[best_idx]) {
                # Compare words lexicographically (byte order)
                if (words[j] < words[best_idx]) {
                    best_idx = j
                }
            }
        }

        # Swap elements i and best_idx
        if (i != best_idx) {
            tmp_word = words[i]
            words[i] = words[best_idx]
            words[best_idx] = tmp_word

            tmp_count = word_counts[i]
            word_counts[i] = word_counts[best_idx]
            word_counts[best_idx] = tmp_count
        }

        # Print the i-th best
        printf "%d %s\n", word_counts[i], words[i]
    }
}
'

exit 0
